@router.post("", response_model=Ticket, status_code=201)
def create_ticket(data: TicketCreate) -> Ticket:
    """Create a ticket and translate invalid titles to HTTP 422."""
    try:
        return submit_ticket(data)
    except InvalidTitle as exc:
        raise HTTPException(422, str(exc)) from exc

def submit_ticket(data: TicketCreate) -> Ticket:
    """Trim the title before applying the minimum-length rule."""
    title = data.title.strip()
    if len(title) < 5:
        raise InvalidTitle("Title needs at least five characters after trimming")
    return insert_ticket(data.model_copy(update={"title": title}))

def insert_ticket(data: TicketCreate) -> Ticket:
    """Insert a new ticket with open status and return its record."""
    def insert(db):
        cur = db.execute(
            "INSERT INTO tickets (title, priority, status) VALUES (?, ?, ?)",
            (data.title, data.priority, "open"),
        )
        return Ticket(id=cur.lastrowid, title=data.title, priority=data.priority, status="open")

    return run_db(insert)

def run_db(operation: Callable[[sqlite3.Connection], T]) -> T:
    """Run each attempt in a fresh transaction and retry only lock errors."""
    for attempt in range(SETTINGS.db_attempts):
        try:
            with closing(sqlite3.connect(SETTINGS.db_path, timeout=0)) as db:
                db.row_factory = sqlite3.Row
                with db:
                    return operation(db)
        except sqlite3.OperationalError as exc:
            if "locked" not in str(exc).lower() or attempt + 1 == SETTINGS.db_attempts:
                raise
            time.sleep(SETTINGS.retry_base_seconds * (2 ** attempt))
    raise RuntimeError("At least one database attempt is required")

